        static float Ease(float t){return t<.5f?4*t*t*t:1-(float)Math.Pow(-2*t+2,3)/2;}
        public static void Run(Content content,Action<bool,string> check){
            var w=New(content);var g=w.Goose;g.Task=Activity.Sleep;g.Target=g.Pos;g.Velocity=new V(151,0);g.MovingFoot=0;g.FootOrigin=g.Pos;g.FootDestination=g.Pos+new V(30,0);g.FootTime=.06f;g.StepDuration=.1f;g.LeftFoot=g.FootOrigin+(g.FootDestination-g.FootOrigin)*Ease(.6f);float before=g.LeftFoot.X;w.Update(.01f);check(g.LeftFoot.X>=before&&g.StepDuration==.1f,"Braking across the speed threshold cannot reverse a planted step");
            w=New(content);g=w.Goose;g.Task=Activity.Chase;w.Pointer=g.Pos+new V(500,0);g.Velocity=new V(149,0);g.MovingFoot=0;g.FootOrigin=g.Pos;g.FootDestination=g.Pos+new V(30,0);g.FootTime=.06f;g.StepDuration=.2f;g.LeftFoot=g.FootOrigin+(g.FootDestination-g.FootOrigin)*Ease(.3f);w.Update(.01f);check(g.Velocity.Length>150&&g.StepDuration==.2f&&Math.Abs(g.LeftFoot.X-(g.FootOrigin.X+30*Ease(.35f)))<.001f,"Acceleration keeps the duration chosen at step start");float previous=V.Distance(g.LeftFoot,g.FootOrigin);for(int i=0;i<8;i++){w.Pointer=g.Pos+new V(-400,i%2==0?400:-400);w.Update(.01f);float distance=V.Distance(g.LeftFoot,g.FootOrigin);if(distance+.001f<previous)throw new Exception("Step reversed in a sharp turn");previous=distance;}check(true,"Sharp turns retain monotonic step progress");
            w=New(content);w.Data.Scale=2;w.Friend.Place(new V(700,350));w.Update(0);check(Math.Abs(V.Distance(w.Friend.LeftFoot,w.Friend.Pos)-5.1f)<.001f,"Companion foot spacing follows its smaller effective scale");
            w.Paused=true;w.Data.Scale=1;w.Goose.FeetReady=w.Friend.FeetReady=false;w.Update(0);check(Math.Abs(V.Distance(w.Friend.LeftFoot,w.Friend.Pos)-2.55f)<.001f,"Changing size while paused immediately rebuilds companion feet");w.Data.Scale=2;
            w.Goose.Coating=Coating.Mud;w.Goose.TrailRemaining=1;w.LandFoot(w.Goose,new V(450.3f,350.7f));Mark mark=w.Marks[0];float landingScale=mark.Scale;V landingPos=mark.Pos;w.Data.Scale=1;w.Data.Hat="Sunhat";check(mark.Scale==landingScale&&mark.Pos.X==landingPos.X&&mark.Pos.Y==landingPos.Y,"Footprints snapshot landing size and position independently of later appearance changes");
            using(var cache=new FootprintRenderer())using(var full=new Bitmap(1000,700))using(var crop=new Bitmap(800,600)){
                using(var fg=Graphics.FromImage(full))cache.Draw(fg,w);using(var cg=Graphics.FromImage(crop)){cg.TranslateTransform(-137,-91);cache.Draw(cg,w);}bool equal=true;for(int y=320;y<385;y++)for(int x=418;x<483;x++)if(full.GetPixel(x,y)!=crop.GetPixel(x-137,y-91))equal=false;check(equal&&cache.Count==1,"Cached footprint pixels remain identical across moving and resized overlay crops");
                mark.Age=9;using(var faded=new Bitmap(1000,700))using(var fg=Graphics.FromImage(faded)){cache.Draw(fg,w);check(faded.GetPixel(450,351).A<full.GetPixel(450,351).A,"Cached footprint fading changes opacity without moving the print");}
                w.Marks.Clear();using(var fg=Graphics.FromImage(full))cache.Draw(fg,w);check(cache.Count==0,"Clearing or expiring prints releases cached stamps");
                for(int i=0;i<256;i++)w.Marks.Add(new Mark{Pos=new V(100+i*2,400),Scale=2,Angle=i*.01f});using(var fg=Graphics.FromImage(full))cache.Draw(fg,w);check(cache.Count==256,"Footprint cache remains bounded by the shared 256-print limit");cache.Dispose();check(cache.Count==0,"Overlay shutdown disposes all cached footprint images");
            }
            w=New(content);w.Goose.MovingFoot=0;w.PlaceObject(ToyKind.Pond,w.Goose.Pos);w.UpdateSurface(w.Goose);check(w.Goose.Swimming&&w.Goose.MovingFoot<0&&!w.Goose.FeetReady,"Entering water cancels the active land step");w.Objects.Clear();w.UpdateSurface(w.Goose);w.Update(0);check(!w.Goose.Swimming&&w.Goose.FeetReady&&w.Goose.MovingFoot<0,"Leaving water rebuilds planted feet without resuming a stale step");
            Appearance(content,check);
            w=New(content);w.Data.Scale=2;w.Goose.Place(new V(70,130));V countdown=Art.DismissPosition(w);check(countdown.X>=0&&countdown.Y>=0&&countdown.X+72<=w.Width&&countdown.Y+36<=w.Height,"Dismissal countdown stays on the selected display near screen edges");var edgeWater=w.PlaceObject(ToyKind.Pond,new V(0,0));check(edgeWater.Pos.X-edgeWater.Size.X/2>=14&&edgeWater.Pos.Y-edgeWater.Size.Y/2>=14,"Surface placement keeps move and remove handles visible at screen edges");using(var layer=new DesktopOverlay(w,new Rectangle(-10000,-10000,1280,752),true)){w.Editing=true;layer.BeginDrag(edgeWater.Pos+edgeWater.Size/2);layer.MoveDrag(new V(5000,5000),.02f);layer.ReleaseDrag();check(edgeWater.Pos.X+edgeWater.Size.X/2<=w.Width-14&&edgeWater.Pos.Y+edgeWater.Size.Y/2<=w.Height-14,"Resizing water keeps its resize handle inside the working area");}
            string folder=Path.Combine(Store.Root,"import-fixtures");Directory.CreateDirectory(folder);string png=Path.Combine(folder,"picture.png"),jpeg=Path.Combine(folder,"photo.jpg"),gif=Path.Combine(folder,"animation.gif"),bad=Path.Combine(folder,"incomplete.png"),locked=Path.Combine(folder,"locked.png");
            using(var image=new Bitmap(24,24)){using(var drawing=Graphics.FromImage(image))drawing.Clear(Color.CornflowerBlue);image.Save(png,ImageFormat.Png);image.Save(jpeg,ImageFormat.Jpeg);image.Save(locked,ImageFormat.Png);}
