            File.WriteAllBytes(gif,gifBytes);File.WriteAllText(bad,"not a complete picture");
            ImportResult result;using(var held=new FileStream(locked,FileMode.Open,FileAccess.ReadWrite,FileShare.None))result=Pictures.Import(new[]{png,bad,jpeg,locked,gif},CancellationToken.None);check(result.Imported==3&&result.Errors.Count==2,"Mixed PNG/JPEG/animated-GIF imports skip corrupt and locked files without stopping the batch");check(!Directory.GetFiles(Path.Combine(Store.Root,"Pictures"),"*.tmp").Any(),"Imports leave no partially published temporary files");result=Pictures.Import(new[]{png},CancellationToken.None);check(result.Imported==1&&File.Exists(Path.Combine(Store.Root,"Pictures","picture (2).png")),"Duplicate picture imports preserve existing files");
            using(var cancel=new CancellationTokenSource()){cancel.Cancel();int count=Directory.GetFiles(Path.Combine(Store.Root,"Pictures")).Length;result=Pictures.Import(new[]{png},cancel.Token);check(result.Imported==0&&count==Directory.GetFiles(Path.Combine(Store.Root,"Pictures")).Length,"Cancelling an import publishes no further pictures");try{Pictures.Publish(png,File.ReadAllBytes(png),Path.Combine(Store.Root,"Pictures"),cancel.Token);throw new Exception("Cancelled publish completed");}catch(OperationCanceledException){}check(!Directory.GetFiles(Path.Combine(Store.Root,"Pictures"),"*.tmp").Any(),"Cancellation cleans temporary files before publication");}
            string stock=Path.Combine(Store.Root,"Pictures","renamed-stock.png"),custom=Path.Combine(Store.Root,"Pictures","honk.png");File.Copy(StockFixture(),stock);File.Copy(png,custom,true);string customHash=Pictures.Hash(custom);Pictures.MigrateStock(AppDomain.CurrentDomain.BaseDirectory,Store.Root);check(Pictures.Hash(stock)==Pictures.Hash(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Packs","Images","honk.png"))&&Pictures.Hash(custom)==customHash,"Stock honk migration replaces recognized copies while preserving customized pictures");string migrated=Pictures.Hash(stock);Pictures.MigrateStock(AppDomain.CurrentDomain.BaseDirectory,Store.Root);check(Pictures.Hash(stock)==migrated,"Stock picture migration is safe to repeat");
            using(var session=new DesktopSession(new SaveData{Sound=false},new Content(Store.Root),"",true)){
                IntPtr owner=session.DialogOwner.Handle;for(int i=0;i<4;i++){session.TestToolboxCycle();session.RunModalTool(o=>check(o.Handle==owner&&!o.IsDisposed&&session.World.Paused,"Import owner survives a closed Toy Box, cycle "+(i+1)));}check(!session.World.Paused&&!session.IsExited,"Modal tools restore the previous running state");session.World.Paused=true;session.RunModalTool(o=>{});check(session.World.Paused,"Modal tools preserve an already paused state");session.RunModalTool(o=>session.ExitThread());check(session.IsExited&&session.DialogOwner.IsDisposed&&!Application.OpenForms.Cast<Form>().Any(),"Immediate quit during a content tool disposes the stable dialog owner and all overlays");
            }
        }
        static string StockFixture(){string path=Path.Combine(Store.Root,"import-fixtures","stock-honk-0.3.png");using(var input=typeof(PatchTests).Assembly.GetManifestResourceStream("DesktopGoose2.Tests.StockHonk"))using(var output=File.Create(path))input.CopyTo(output);return path;}
        [System.Runtime.InteropServices.DllImport("user32.dll")]static extern int GetGuiResources(IntPtr process,int flags);
        public static void Native(Content content,System.Collections.Generic.List<string> output){
            string original=Store.Root;Store.Root=Path.Combine(Program.ArtifactsFolder,"test-patch-native-"+Guid.NewGuid().ToString("N"));UserContent.Initialize(AppDomain.CurrentDomain.BaseDirectory,null,false);
            try{
                using(var session=new DesktopSession(new SaveData{Sound=false},new Content(Store.Root),"",true)){
                    for(int cycle=0;cycle<3;cycle++){
                        if(cycle>0)session.TestToolboxCycle();DialogResult result=DialogResult.None;session.RunModalTool(owner=>{using(var picker=new OpenFileDialog{Title="Goose import regression check",InitialDirectory=Store.Root,Filter="Pictures|*.png;*.jpg;*.gif"})using(var close=new System.Windows.Forms.Timer{Interval=250}){close.Tick+=(s,e)=>SecondHonk.Native.CloseOwnedDialogs(owner.Handle);close.Start();result=picker.ShowDialog(owner);close.Stop();}});
                        if(result!=DialogResult.Cancel||session.IsExited||session.World.Paused)throw new Exception("Native file-dialog regression failed");
                    }output.Add("PASS  Real Windows file picker opens and cancels with no Toy Box, a closed Toy Box, and a repeatedly closed Toy Box; gameplay resumes.");
                    DialogResult legacy=DialogResult.None;session.RunModalTool(owner=>{using(var picker=new FolderBrowserDialog{Description="Goose legacy import regression check",SelectedPath=Store.Root})using(var close=new System.Windows.Forms.Timer{Interval=250}){close.Tick+=(s,e)=>SecondHonk.Native.CloseOwnedDialogs(owner.Handle);close.Start();legacy=picker.ShowDialog(owner);close.Stop();}});if(legacy!=DialogResult.Cancel||session.IsExited)throw new Exception("Native legacy picker failed");output.Add("PASS  Real legacy folder picker uses the stable owner and cancels without crashing.");
                    using(var close=new System.Windows.Forms.Timer{Interval=250}){close.Tick+=(s,e)=>SecondHonk.Native.CloseOwnedDialogs(session.DialogOwner.Handle);close.Start();session.RunModalTool(owner=>{throw new IOException("Simulated file picker failure for regression testing.");});close.Stop();}if(session.IsExited||session.World.Paused)throw new Exception("Recoverable dialog error terminated gameplay");output.Add("PASS  A dialog-opening failure shows one recoverable message and restores gameplay without exiting.");
                    session.RunModalTool(owner=>{using(var picker=new OpenFileDialog{Title="Goose quit-during-import check",InitialDirectory=Store.Root})using(var close=new System.Windows.Forms.Timer{Interval=250}){close.Tick+=(s,e)=>{close.Stop();session.ExitThread();};close.Start();picker.ShowDialog(owner);}});if(!session.IsExited||!session.DialogOwner.IsDisposed||Application.OpenForms.Cast<Form>().Any())throw new Exception("Quit did not clean up the native file picker");output.Add("PASS  Immediate quit during a real file picker closes its owner, picker and overlays.");
                }
                using(var finished=new ManualResetEvent(false))using(var session=new DesktopSession(new SaveData{Sound=false},new Content(Store.Root),"",true)){
                    session.RunModalTool(owner=>{using(var progress=new ImportProgress(token=>{while(!token.IsCancellationRequested)Thread.Sleep(10);finished.Set();return new ImportResult();}))using(var close=new System.Windows.Forms.Timer{Interval=250}){close.Tick+=(s,e)=>{close.Stop();session.ExitThread();};close.Start();progress.ShowDialog(owner);}});if(!session.IsExited||!finished.WaitOne(2000))throw new Exception("Import worker did not cancel on quit");output.Add("PASS  Quitting the import progress dialog cancels its worker and cleans up immediately.");
                }
                var w=New(content);w.Editing=true;for(int i=0;i<16;i++)w.PlaceObject((ToyKind)(i%7),new V(130+i%5*200,150+i/5*150));for(int i=0;i<256;i++)w.Marks.Add(new Mark{Pos=new V(100+i%16*65,110+i/16*32),Angle=i*.1f,Scale=i%2==0?1.5f:1.275f,Coating=i%2==0?Coating.Mud:Coating.Wet});
                using(var bg=new DesktopOverlay(w,new Rectangle(-10000,-10000,1280,752)))using(var toys=new DesktopOverlay(w,new Rectangle(-10000,-10000,1280,752),true)){
                    bg.Show();toys.Show();bg.RenderFrame();toys.RenderFrame();int before=GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);for(int i=0;i<180;i++){w.Goose.Pos+=new V(i%2==0?.3f:-.3f,0);bg.RenderFrame();toys.RenderFrame();}int after=GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);if(after>before+3)throw new Exception("Max-footprint workload leaked GDI handles");output.Add("PASS  Maximum 256 footprints, 16 objects and both geese render over 180 dual-layer frames; GDI "+before+" -> "+after+".");
                }
                string picture=Path.Combine(Store.Root,"Pictures","honk.png"),animation=Path.Combine(Store.Root,"Pictures","animation.gif");File.WriteAllBytes(animation,gifBytes);int baseline=GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);for(int i=0;i<24;i++)using(var gift=new GooseWindow("",i%2==0?picture:animation)){gift.Location=new Point(-10000,-10000);gift.Show();Application.DoEvents();using(var bmp=new Bitmap(gift.Width,gift.Height))gift.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));gift.Close();}GC.Collect();GC.WaitForPendingFinalizers();int final=GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);if(final>baseline+3)throw new Exception("Repeated picture windows leaked GDI handles");output.Add("PASS  24 validated PNG/animated-GIF windows open/render/close; GDI "+baseline+" -> "+final+".");
            }finally{Store.Root=original;}
        }
        static void Appearance(Content content,Action<bool,string> check){
            using(var sheet=new Bitmap(1020,720))using(var sg=Graphics.FromImage(sheet)){
                sg.Clear(Color.FromArgb(229,233,224));int row=0;foreach(float scale in new[]{1f,1.5f,2f}){int column=0;foreach(string hat in new[]{"None","Scarf","Sunhat"}){var w=New(content);w.Data.Scale=scale;w.Data.Hat=hat;w.Goose.Place(new V(85,190));w.Friend.Place(new V(260,190));w.Goose.Direction=w.Goose.HeadDirection=w.Friend.Direction=w.Friend.HeadDirection=-.3f;w.Update(0);using(var cell=new Bitmap(340,240))using(var cg=Graphics.FromImage(cell)){Art.Scene(cg,w);int dark=0,red=0,gold=0;for(int y=35;y<215;y++)for(int x=205;x<335;x++){Color p=cell.GetPixel(x,y);if(p.A>100&&p.R<70&&p.G<70&&p.B<70)dark++;if(p.A>100&&p.R>170&&p.G<100&&p.B<90)red++;if(p.A>100&&p.R>200&&p.G>170&&p.G<210&&p.B>100&&p.B<160)gold++;}check(dark>20&&(hat!="Scarf"||red>5)&&(hat!="Sunhat"||gold>20),"Canada companion and shared "+hat+" appearance render at scale "+scale);sg.DrawImageUnscaled(cell,column*340,row*240);using(var f=new Font("Segoe UI",10))sg.DrawString(hat+" · "+scale+"x",f,Brushes.Black,column*340+12,row*240+10);w.Data.ReducedMotion=true;w.Exploding=true;w.ExplosionTime=.1f;using(var fade=new Bitmap(340,240))using(var fg=Graphics.FromImage(fade))Art.Scene(fg,w);}column++;}row++;}sheet.Save(Path.Combine(Program.ArtifactsFolder,"companion-appearance-0.3.1.png"));
            }
        }
